The path prefix check using startsWith() is unsafe and can produce incorrect results. For example, if os.homedir() is "/home/user" and absolutePath is "/home/user-data/file.md", this would incorrectly match and generate a relative path with ~/. This should compare normalized paths with proper directory boundaries.
```suggestion
function isWithinDir(baseDir: string, targetPath: string): boolean {
  const base = path.resolve(baseDir)
  const target = path.resolve(targetPath)
  const rel = path.relative(base, target)
  if (!rel || rel === "") return true
  return !rel.startsWith(".." + path.sep) && rel !== ".." && !path.isAbsolute(rel)
}

function toConfigPath(absolutePath: string): string {
  const normalized = path.resolve(absolutePath)
  const instanceDir = path.resolve(Instance.directory)
  const homeDir = path.resolve(os.homedir())

  if (isWithinDir(instanceDir, normalized)) {
    return "./" + path.relative(instanceDir, normalized).replace(/\\/g, "/")
  } else if (isWithinDir(homeDir, normalized)) {
    return "~/" + path.relative(homeDir, normalized).replace(/\\/g, "/")
  }
  return normalized
```

